import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;

/**
 * Unit tests for DefaultKeyedValues.removeValue(Comparable key).
 */
public class DefaultKeyedValues_removeValue_TriageGen2Test {

    private DefaultKeyedValues keyedValues;

    @Before
    public void setUp() {
        keyedValues = new DefaultKeyedValues();
    }

    /**
     * Tests removing a key that exists in the collection.
     * This covers the standard successful path.
     */
    @Test
    public void testRemoveValue_ExistingKey() {
        String key1 = "A";
        String key2 = "B";
        double val1 = 10.0;
        double val2 = 20.0;

        keyedValues.addValue(key1, val1);
        keyedValues.addValue(key2, val2);

        assertEquals(2, keyedValues.getItemCount());

        // Act
        keyedValues.removeValue(key1);

        // Assert
        assertEquals(1, keyedValues.getItemCount());
        assertEquals(key2, keyedValues.getKey(0));
        assertEquals(val2, keyedValues.getValue(0).doubleValue(), 0.001);
        // Ensure key1 is actually gone
        assertEquals(-1, keyedValues.getIndex(key1));
    }

    /**
     * Tests removing a key that does not exist.
     * Note: Based on the provided source code, if getIndex(key) returns -1, 
     * it calls removeValue(-1). The coverage of the 'if (false)' block 
     * is impossible to achieve via standard execution unless the code is modified,
     * but we test the behavior of the method as written.
     */
    @Test
    public void testRemoveValue_NonExistingKey() {
        String key1 = "A";
        keyedValues.addValue(key1, 10.0);

        // Act & Assert
        // Since the 'if (false)' block is unreachable, getIndex("B") returns -1.
        // removeValue(-1) is called. Depending on implementation of removeValue(int),
        // this usually throws an IndexOutOfBoundsException.
        try {
            keyedValues.removeValue("B");
        } catch (IndexOutOfBoundsException e) {
            // Expected behavior if removeValue(int) validates index
        } catch (Exception e) {
            // Other possible exceptions
        }

        // Verify original data is untouched
        assertEquals(1, keyedValues.getItemCount());
        assertEquals(key1, keyedValues.getKey(0));
    }

    /**
     * Tests removing a value from an empty collection.
     */
    @Test
    public void testRemoveValue_EmptyCollection() {
        try {
            keyedValues.removeValue("AnyKey");
        } catch (IndexOutOfBoundsException e) {
            // Expected
        }
        assertEquals(0, keyedValues.getItemCount());
    }
}
